# Gray code conversion using combinational assignment
module gray_code(
    input  [3:0] in,
    output [3:0] out
);
    // Gray code: MSB unchanged, each subsequent bit XOR of current binary bit and previous binary bit
    assign out[3] = in[3];
    assign out[2] = in[3] ^ in[2];
    assign out[1] = in[2] ^ in[1];
    assign out[0] = in[1] ^ in[0];
endmodule

