module debounce(
    input clk,
    input PB,
    output reg PB_state
);
    // Width to count up to 4096 (2^12)
    localparam CNT_MAX = 12'd4095; // count from 0..4095 => 4096 cycles

    // Internal registers
    reg        cur_state;   // holds the new PB value when it changes
    reg [11:0] PB_cnt;      // 12‑bit counter (0‑4095)
    reg        pb_d;        // previous value of PB for edge detection

    // Initialise registers (simulation only; in hardware they will be reset by power‑up)
    initial begin
        cur_state = 1'b0;
        PB_cnt    = 12'd0;
        pb_d      = 1'b0;
        PB_state  = 1'b0;
    end

    // Main debounce logic
    always @(posedge clk) begin
        // Detect change on PB
        if (PB != pb_d) begin
            // New input detected – capture it and start counting
            cur_state <= PB;
            PB_cnt    <= 12'd1;   // start counting from 1 as the spec demands
        end else if (PB_cnt != 12'd0) begin
            // No change, but we are still counting
            if (PB_cnt == CNT_MAX) begin
                // Counter has reached 4096 cycles – commit the stable value
                PB_state <= cur_state;
                PB_cnt   <= 12'd0; // reset counter
            end else begin
                // Keep counting
                PB_cnt <= PB_cnt + 12'd1;
            end
        end
        // Store current PB for next‑cycle comparison
        pb_d <= PB;
    end
endmodule

