module d_ff_en(
    input D,
    input EN,
    input CLK,
    output reg Q
);
    // D-type flip‑flop with enable.
    // On each rising edge of CLK, if EN is asserted (high) the value of D
    // is captured into Q. When EN is low, Q retains its previous value.
    // No asynchronous reset is defined – the default Power‑on state
    // of Q is unknown (x) and will be defined by the surrounding design.

    always @(posedge CLK) begin
        if (EN) begin
            Q <= D;   // capture D when enabled
        end
        // else retain Q (no else branch needed because non‑blocking
        // assignment keeps the previous value)
    end
endmodule

