# Barrel shifter – 4‑bit left logical barrel shifter
REG data_out [4] @clk.pos reset.sync->0 NEXT=next_data_out

COMB next_data_out
  shift_amount=0 -> data_in
| shift_amount=1 -> {data_in[2:0], 1'b0}
| shift_amount=2 -> {data_in[1:0], 2'b0}
| shift_amount=3 -> {data_in[0], 3'b0}
| * -> 4'b0000

module shift_register (
    input CLK,
    input LOAD,
    input SHIFT,
    input [3:0] DATA_IN,
    output reg [3:0] DATA_OUT
);
    // Parallel load and shift‑right register.
    // Priority: LOAD > SHIFT > hold (when both are low).
    always @(posedge CLK) begin
        if (LOAD) begin
            // Load parallel data
            DATA_OUT <= DATA_IN;
        end else if (SHIFT) begin
            // Shift right by one position, MSB gets 0 (or could be left unchanged)
            // Here we insert a 0 on the MSB; adjust if a different fill is required.
            DATA_OUT <= {1'b0, DATA_OUT[3:1]};
        end else begin
            // Hold current value
            DATA_OUT <= DATA_OUT;
        end
    end
endmodule

module sky130_fd_sc_lp__a2bb2oi (
