module clk_delay #(
    parameter MAX_DELAY_NS = 10
) (
    input  wire clk_in,
    output wire clk_out,
    input  wire [3:0] delay   // Delay in nanoseconds: 0-10
);

    // ---------------------------------------------------------------------
    // NOTE:
    //   The following implementation uses Verilog's *delay control* ("#")
    //   to model the propagation delay.  This construct is only a **simulation
    //   model** – most synthesis tools will ignore the delay and will infer a
    //   direct connection.  For a truly synthesizable solution the delay would
    //   have to be implemented with a PLL, DLL or a high‑frequency clock that
    //   can be divided down to 1 ns resolution, which is technology‑specific
    //   and beyond the scope of a generic RTL description.
    // ---------------------------------------------------------------------

    // A temporary wire is used so that the delay control can be attached to
    // an assign statement.  The delay value is taken from the input `delay`
    // (0‑10 ns).  Because the delay argument of an assign must be a constant
    // expression, we expand the possible values with a generate‑case construct.

    reg  delayed_reg;
    always @(posedge clk_in or posedge delayed_reg) begin
        // No functional logic – the always block is only needed to create a
        // procedural context for the *variable* delay below.
    end

    // Using a combinational generate block to select the appropriate constant
    // delay for each possible value of `delay` (0‑10 ns).  This is synthesizable
    // only for simulation; hardware will see a direct connection.
    generate
        genvar i;
        for (i = 0; i <= MAX_DELAY_NS; i = i + 1) begin : delay_gen
            if (i == 0) begin
                assign clk_out = clk_in;
            end else begin
                // The delay literal must be a constant, hence the `i` value.
                // The `#(i)` syntax creates a delay of `i` time‑units.  The
                // simulation time‑unit is assumed to be 1 ns (set by the
                // `timescale` directive at the top of the file).
                assign #(i) clk_out = clk_in;
            end
        end
    endgenerate

endmodule

module logic_function(
  input A,
  input B,
  input C,
  output Y1,
  output Y2,
  output Y3
);
  // Y1 is always equal to A
  assign Y1 = A;

  // When C = 0, Y2 follows B; otherwise Y2 is forced to 0
  assign Y2 = (C == 1'b0) ? B : 1'b0;

  // When C = 1, Y3 follows B; otherwise Y3 is forced to 0
  assign Y3 = (C == 1'b1) ? B : 1'b0;

endmodule

