module my_module (
    X   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    B2  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);
    // ---------------------------------------------------------------------
    // Port declaration – one output (single‑bit) and nine inputs.
    // ---------------------------------------------------------------------
    output  X;
    input   A1, A2, A3, B1, B2, VPWR, VGND, VPB, VNB;

    // ---------------------------------------------------------------------
    // Internal helper wires for each conditional term.
    // ---------------------------------------------------------------------
    wire term_and;   // A2 AND A3
    wire term_or;    // B2 OR VPWR
    wire term_xor;   // VPB XOR VNB

    assign term_and = A2 & A3;
    assign term_or  = B2 | VPWR;
    assign term_xor = VPB ^ VNB;

    // ---------------------------------------------------------------------
    // Priority combinational logic as described in the specification.
    //   1) A1 == 1 → term_and
    //   2) A1 == 0 && B1 == 1 → term_or
    //   3) otherwise → term_xor
    // ---------------------------------------------------------------------
    assign X = A1               ? term_and :
               (!A1 && B1)      ? term_or  :
                                 term_xor;

    // ---------------------------------------------------------------------
    // Instantiation of the sky130 standard cell – we connect all of its
    //   ports to the surrounding signals so that the design “interfaces” with
    //   the cell.  The cell's output is not required for the functional
    //   description, therefore we tie it to a dummy wire.
    // ---------------------------------------------------------------------
    wire [31:0] dummy_cell_X;   // 32‑bit output of the a32o cell (unused)

    sky130_fd_sc_lp__a32o_0 u_a32o (
        .X   (dummy_cell_X),   // 32‑bit output – ignored
        .A1  (A1),
        .A2  (A2),
        .A3  (A3),
        .B1  (B1),
        .B2  (B2),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB (VPB),
        .VNB (VNB),
        .VDD (VPWR)   // tie VDD to the primary power rail
    );

endmodule

