module add5_4bit (
    input  [3:0] A,
    output [3:0] Y
);
    // Bit‑wise addition of constant 5 (4'b0101) to A.
    // No '+' operator is used – the logic is a handcrafted ripple‑carry adder.

    // ---- Bit 0 (LSB) ----------------------------------------------------
    // 5[0] = 1
    wire s0 = ~A[0];            // sum bit 0 = A[0] ^ 1
    wire c1 =  A[0];            // carry out of bit 0 = A[0] & 1

    // ---- Bit 1 ----------------------------------------------------------
    // 5[1] = 0
    wire s1 = A[1] ^ c1;        // sum bit 1
    wire c2 = A[1] & c1;        // carry out of bit 1

    // ---- Bit 2 ----------------------------------------------------------
    // 5[2] = 1
    wire s2 = (~A[2]) ^ c2;     // sum bit 2 = A[2] ^ 1 ^ c2
    wire c3 = A[2] | c2;        // carry out of bit 2 = (A[2] & 1) | (1 & c2) | (A[2] & c2)

    // ---- Bit 3 (MSB) ----------------------------------------------------
    // 5[3] = 0
    wire s3 = A[3] ^ c3;        // sum bit 3
    // Carry out of the MSB (c4) is ignored – overflow is discarded.

    assign Y = {s3, s2, s1, s0};
endmodule

