);
    // ------------------------------------------------------------
    // 3‑input NOR gate built from primitive MOSFETs of the
    // sky130_fd_sc_ms library.  No external cells are instantiated.
    // ------------------------------------------------------------
    // Supply pins are assumed to be available in the surrounding
    // hierarchy; we simply tie them to Verilog supplies.
    supply1 VPWR; // positive power rail
    supply0 VGND; // ground

    // Internal nets for the series‑PMOS network.
    wire p_int1, p_int2;

    // -----------------------------------------------------------------
    // Pull‑up network (PMOS devices in series).  The output is pulled
    // high only when *all* inputs are low.
    // -----------------------------------------------------------------
    pmos pA (p_int1 , VPWR , A );   // first PMOS, source=VPWR, drain=p_int1
    pmos pB (p_int2 , p_int1, B ); // second PMOS, source=p_int1, drain=p_int2
    pmos pC (Y      , p_int2, C ); // third PMOS, source=p_int2, drain=Y

    // -----------------------------------------------------------------
    // Pull‑down network (NMOS devices in parallel).  Any high input
    // pulls the output low.
    // -----------------------------------------------------------------
    nmos nA (Y , VGND , A );
    nmos nB (Y , VGND , B );
    nmos nC (Y , VGND , C );

