module custom_module (
    output X,
    input  A1,
    input  A2,
    input  [1:0] B1
);
    // Combinational logic implementing the truth‑table described:
    //   A1 A2 | X (depends on B1)
    //   1  0  | 1                     (override, B1 ignored)
    //   0  1  | 0                     (override, B1 ignored)
    //   1  1  | B1[1] (high for 2'b10,2'b11)
    //   0  0  | B1[0] (high for 2'b01,2'b11)
