module TFFSR (D, S, R, CLK, Q, QN);
input D;
input S;
input R;
input CLK;
output reg Q;
output QN;

// Asynchronous set (S) and reset (R) with priority over normal operation.
// If both S and R are high simultaneously, Q is forced to X (undefined).
// Otherwise, on the rising edge of CLK, the flip‑flop toggles when D (T) is 1.

always @(posedge CLK or posedge S or posedge R) begin
    if (S && R) begin
        Q <= 1'bx;               // undefined when both set and reset asserted
    end else if (S) begin
        Q <= 1'b1;               // asynchronous set
    end else if (R) begin
        Q <= 1'b0;               // asynchronous reset
    end else begin
        if (D)                    // T = 1 → toggle
            Q <= ~Q;
        else
            Q <= Q;               // hold current state
    end
end

assign QN = ~Q;                 // complementary output

endmodule

