module adder_subtractor_4bit (
    input  [3:0] a,
    input  [3:0] b,
    input        sub,   // 0 = add, 1 = subtract (a - b)
    output reg [3:0] s
);
    // ---------------------------------------------------------------------
    // Design choice
    // ---------------------------------------------------------------------
    // A subtraction can be performed by adding the two's‑complement of `b`.
    // Two's‑complement of `b` = ~b + 1.  By XOR‑ing `b` with the `sub` signal we
    // obtain ~b when sub=1 and b when sub=0.  Adding the `sub` signal as the
    // carry‑in supplies the required +1 for the two's‑complement case.
    // The expression below is completely combinational and will be inferred
    // as a single 4‑bit adder with a carry‑in.
    // ---------------------------------------------------------------------

    // Intermediate signals (pure combinational wires)
    wire [3:0] b_xor   = b ^ {4{sub}};   // b  when sub=0, ~b when sub=1
    wire       cin     = sub;           // 0 for addition, 1 for subtraction
    wire [4:0] result   = a + b_xor + cin; // 5‑bit to capture carry/borrow

    // Output register (the spec asks for `reg` – we drive it combinationally)
