// Plain Verilog implementation (<=200 lines)
// ------------------------------------------------------------
module binary_output(
  input  [9:0] binary_in,
  output reg [21*8-1:0] binary_out // 21 ASCII characters, 8 bits each
);

  // Internal character buffer (each element holds one ASCII byte)
  reg [7:0] buf [0:20];
  integer i;
  integer first_one; // index of the most‑significant ‘1’ in binary_in

  // Convert binary_in to ASCII characters
  always @* begin
    // Find the position of the most significant 1 (if any)
    first_one = -1;
    for (i = 9; i >= 0; i = i - 1) begin
      if (binary_in[i] == 1'b1 && first_one == -1) begin
        first_one = i;
      end
    end

    // -----------------------------------------------------------------
    // Build the minimal representation (no leading zeros)
    // -----------------------------------------------------------------
    // Start with a leading pipe
    buf[0] = "|";
    // If the value is zero, we output a single '0'
    if (first_one == -1) begin
      buf[1] = "0";
      // Position after the minimal string
      i = 2; // next free index
    end else begin
      // Copy bits from MSB (first_one) down to LSB into ASCII '0'/'1'
      for (i = first_one; i >= 0; i = i - 1) begin
        buf[1 + (first_one - i)] = binary_in[i] ? "1" : "0";
      end
      i = 1 + (first_one + 1); // next free index after the minimal part
    end
    // Closing pipe for the first field
    buf[i] = "|";
    i = i + 1;

    // -----------------------------------------------------------------
    // Build the zero‑padded 10‑bit representation
    // -----------------------------------------------------------------
    for (int j = 9; j >= 0; j = j - 1) begin
      buf[i] = binary_in[j] ? "1" : "0";
      i = i + 1;
    end
    // Final pipe (optional – kept to match the example layout)
    buf[i] = "|";
    i = i + 1;

    // Fill any remaining positions with spaces (ASCII 32) to reach 21 chars
    while (i < 21) begin
      buf[i] = " ";
      i = i + 1;
    end

    // Pack the character buffer into the output vector (big‑endian order)
    binary_out = {buf[0], buf[1], buf[2], buf[3], buf[4], buf[5], buf[6], buf[7],
                  buf[8], buf[9], buf[10], buf[11], buf[12], buf[13], buf[14],
                  buf[15], buf[16], buf[17], buf[18], buf[19], buf[20]};
  end

endmodule

