module jk_flip_flop (
    input  J,
    input  K,
    input  clk,
    output reg Q
);

    // JK flip‑flop using a case statement on the J‑K inputs.
    // Truth table (at the rising edge of clk):
    // J K | Q_next
    // 0 0 | Q (no change)
    // 0 1 | 0 (reset)
    // 1 0 | 1 (set)
    // 1 1 | ~Q (toggle)
    always @(posedge clk) begin : jk_ff
        case ({J, K})
            2'b00: Q <= Q;          // hold
            2'b01: Q <= 1'b0;       // reset
            2'b10: Q <= 1'b1;       // set
            2'b11: Q <= ~Q;         // toggle
            default: Q <= Q;        // safety fallback
        endcase
    end

endmodule

