  // with all bits cleared.
  integer i;
  initial begin
    for (i = 0; i < MEM_DEPTH; i = i + 1) begin
      mem[i] = {DATA_WIDTH{1'b0}};
    end
  end

  // Synchronous read.  The address is 20‑bit, so it automatically stays
  // within the valid range, but the extra check guarantees correct behaviour
  // if the address ever becomes out of range (e.g., during simulation).
  always @(posedge clk) begin
    if (addr < MEM_DEPTH) begin
      data <= mem[addr];
    end else begin
      data <= {DATA_WIDTH{1'b0}}; // out‑of‑range protection
    end
  end

endmodule

