module my_module (
    Y   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    VPWR,
    VGND,
    VPB ,
    VNB 
);
    // Port directions
    output Y;
    input  A1, A2, A3, B1, VPWR, VGND, VPB, VNB;

    // Internal combinational logic
    //   High‑priority "force‑low" conditions: B1, VGND, and (VPB==0 && VNB==1)
    //   High‑priority "force‑high" conditions: A1&A2&A3, VPWR, (VPB==1 && VNB==0)
    //   If both a force‑high and a force‑low are true simultaneously, the low wins.
    //   The final expression can be written as:
    //       Y = (force_high) & ~ (force_low);
    //   where:
    //       force_high = (A1 & A2 & A3) | VPWR | (VPB & ~VNB);
    //       force_low  = B1 | VGND | (~VPB & VNB);

    wire force_high = (A1 & A2 & A3) | VPWR | (VPB & ~VNB);
    wire force_low  = B1 | VGND | (~VPB & VNB);

    assign Y = force_high & ~force_low;
endmodule

