module output_module(
    input  ctrl1_zone,
    input  ctrl2_zone,
    input  statusb_zone,
    input  [9:0] p1_in,
    input  [9:0] p2_in,
    input  nwp,
    input  ncd2,
    input  ncd1,
    input  system_mode,
    output reg [7:0] m68k_data
);

    // Combinational logic with priority encoding
    //   1) ctrl1_zone high → high‑impedance output
    //   2) ctrl2_zone high → high‑impedance output
    //   3) statusb_zone high → packed status word
    //   4) default → lower 8 bits of p1_in
    always @* begin
        if (ctrl1_zone) begin
            m68k_data = 8'bz;               // 8'bzzzzzzzz
        end else if (ctrl2_zone) begin
            m68k_data = 8'bz;               // 8'bzzzzzzzz
        end else if (statusb_zone) begin
            // {system_mode, nwp, ncd2, ncd1, p2_in[9:8], p1_in[9:8]}
            m68k_data = {system_mode, nwp, ncd2, ncd1,
                         p2_in[9:8], p1_in[9:8]};
        end else begin
            m68k_data = p1_in[7:0];
        end
    end

endmodule

module multi_input_output (
    input [7:0] A,
    input [7:0] B,
    input [7:0] C,
    input [7:0] D,
    input [7:0] E,
    input [7:0] F,
    input [7:0] G,
    input [7:0] H,
    output [7:0] Y
);
    // Intermediate sums – one extra bit to capture carry/borrow
    wire [8:0] sum_ab = A + B;   // 9‑bit to avoid overflow
    wire [8:0] sum_cd = C + D;
    wire [8:0] sum_ef = E + F;
    wire [8:0] sum_gh = G + H;

    // Positive group (A+B)+(E+F) and negative group (C+D)+(G+H)
    wire [8:0] pos_group = sum_ab + sum_ef;
    wire [8:0] neg_group = sum_cd + sum_gh;

    // Final subtraction – still 9‑bit to keep the sign bit
    wire [8:0] result = pos_group - neg_group;

    // Truncate to 8‑bit output (Verilog will drop the MSB)
    assign Y = result[7:0];
endmodule

