| input_bits=3'b001 -> 8'b0000_0010
| input_bits=3'b010 -> 8'b0000_0100
| input_bits=3'b011 -> 8'b0000_1000
| input_bits=3'b100 -> 8'b0001_0000
| input_bits=3'b101 -> 8'b0010_0000
| input_bits=3'b110 -> 8'b0100_0000
| input_bits=3'b111 -> 8'b1000_0000
| * -> 8'b0000_0000

