module four_to_one_mux #(
    parameter WIDTH = 4
) (
    input  [WIDTH-1:0] in0,
    input  [WIDTH-1:0] in1,
    input  [WIDTH-1:0] in2,
    input  [WIDTH-1:0] in3,
    input  [1:0]       sel,
    output reg [WIDTH-1:0] out
);

    // -------------------------------------------------------
    // 4‑to‑1 multiplexer – combinational logic
    // -------------------------------------------------------
    // The case statement provides a clear, synthesizable description.
    // The default branch is added for linting safety; it should never
    // be hit because "sel" is a 2‑bit vector covering all possibilities.
    // -------------------------------------------------------
    always @(*) begin
        case (sel)
            2'b00: out = in0;
            2'b01: out = in1;
            2'b10: out = in2;
            2'b11: out = in3;
            default: out = {WIDTH{1'b0}}; // safe fallback
        endcase
    end

endmodule

module comparator (
    input [15:0] A,
    input [15:0] B,
    output reg result
);
    // The unsigned subtraction B-A produces a borrow when B < A.
    // The MSB of (B-A) is the borrow flag for unsigned arithmetic.
    // If B >= A (i.e., A <= B) then the MSB is 0, otherwise it is 1.
    // Therefore we invert the MSB to obtain the desired result.
    assign result = ~((B - A)[15]);
endmodule

